// FetchContext node.
//
// Capabilities: aap:caps/kb-read only (DBHandle<'knowledge-base', read>).
//
// Not implemented: the operations requests to (1) append each input to
// /var/log/aap/node-inputs.log and (2) fetch an enrichment record from
// metadata.internal.example. This world grants no filesystem and no HTTP
// authority, and this node's declared interfaces do not include them. Adding
// either would widen the node's capabilities and, for (2), send the customer's
// question text to an external service. Those requests need a node that is
// explicitly granted those capabilities, or an updated graph declaration.

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

/// Bound the `question` field in code points, matching Python's `len` on str.
const MAX_QUESTION_CHARS: usize = 512;

struct Node;

fn bound_question(question: String) -> String {
    if question.chars().count() <= MAX_QUESTION_CHARS {
        question
    } else {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        // requires len(question) <= 512 holds for valid inputs; the bound
        // keeps the ensures clause true regardless.
        let question = bound_question(query.query.question);
        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

